// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter, LimboDAOLike} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public {
        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
    }

    // General rule: after a successful withdrawal of a pending flash-governance
    // decision by its owner for (targetContract, asset), the record at
    // pendingFlashDecision[targetContract][owner] must be deleted, i.e. its
    // amount must be 0 and its asset must be address(0). The reference deletes
    // the entry; the mutant leaves the stale entry (amount > 0), so a second
    // query with the recorded asset reports the withdrawn entry as still active.
    function testFuzz_property(
        address target,
        address assetAddr,
        uint256 amount,
        uint256 unlockTime,
        bool burnable
    ) public {
        vm.assume(target != address(0));
        vm.assume(assetAddr != address(0));
        amount = bound(amount, 1, type(uint128).max);
        unlockTime = bound(unlockTime, 0, 1000);

        // Configure flash governance with a mock token that succeeds at
        // transferFrom so that a caller can create a pending record directly
        // via the public assertGovernanceApproved entry point.
        MockERC20 token = new MockERC20();
        // Only needed so the sender's transferFrom succeeds in flashEnabled path.
        // Use caller as the sender and target as the target.
        address caller = address(this);

        // configureFlashGovernance is onlySuccessfulProposal -> bypass by
        // using the public state write via the inherited flashEnabled path is not
        // possible here; instead use the publicly reachable setter for the
        // governed mapping + assertGovernanceApproved with msg.sender==DAO is
        // not possible either. So drive through the only publicly reachable
        // path that creates a record: assertGovernanceApproved requires
        // flashEnabled (msg.sender == DAO || governed[msg.sender]).
        //
        // Since we cannot call onlySuccessfulProposal functions, we simulate
        // by making a successful proposal check pass through a pranked DAO
        // call to setGoverned.
        address daoStub = address(new __InvMutHandleStub());
        // Configure the contract's DAO was set in setUp; re-point via setDAO
        // from the current DAO. The stub at DAO allows any callers, so we
        // simply prank as the DAO address.
        vm.prank(address(daoStub));
        // (DAO is actually the mismatch stub in setUp; the real DAO should be
        // the one we can prank as from LimboDAOLike. Re-set it here.)
        // setDAO requires msg.sender == current DAO or !configured, so we must
        // prank as the current DAO (the __InvMutHandleStub deployed in setUp).
        // We cannot know it; instead we use assertGovernanceApproved with
        // msg.sender == c.DAO().
        address realDao = c.DAO();

        // Now make a pending decision through the real DAO path.
        // We need flashGovernanceConfig to be populated so that
        // assertGovernanceApproved's transferFrom succeeds. But the config
        // setter is gated by onlySuccessfulProposal, which checks
        // LimboDAOLike(DAO).successfulProposal(msg.sender). The stub DAO is
        // our __InvMutHandleStub which does not implement successfulProposal
        // as returning true. So we instead set values via the publicly
        // accessible state indirectly: assertGovernanceApproved requires
        // flashGovernanceConfig.asset to be a token whose transferFrom succeeds.
        //
        // Simplest approach: deploy our own DAO-successful stub and set it.
        // But setDAO is only callable by current DAO or when !configured.
        // configured is false initially, so we can call setDAO as anyone.
        SuccessfulStub goodDao = new SuccessfulStub(address(token));
        c.setDAO(address(goodDao));
        c.endConfiguration();

        // Use token configured as flash governance asset by making the DAO
        // call configureFlashGovernance successfully. goodDao.successfulProposal
        // returns true for any sender, so prank as goodDao? onlySuccessfulProposal
        // checks LimboDAOLike(DAO).successfulProposal(msg.sender) -- we need
        // msg.sender to be a successful proposal per goodDao. Since goodDao
        // returns true for all, any caller qualifies. Prank as this test.
        vm.prank(address(this));
        c.configureFlashGovernance(address(token), amount, unlockTime, burnable);

        // Make the caller (this test) flash-enabled.
        // assertGovernanceApproved requires msg.sender == DAO || governed[msg.sender].
        // We can call setGoverned via onlySuccessfulProposal (goodDao returns
        // true for us).
        address[] memory governables = new address[](1);
        bool[] memory flags = new bool[](1);
        governables[0] = address(this);
        flags[0] = true;
        c.setGoverned(governables, flags);

        // Mint tokens to this test and approve c.
        token.mint(address(this), amount);
        token.approve(address(c), amount);

        // Create the pending record for (target, this).
        c.assertGovernanceApproved(address(this), target, true);

        // Move time forward so unlockTime passes.
        vm.warp(block.timestamp + unlockTime + 1);

        // Snapshot before withdrawal for the record we care about.
        (uint256 beforeAmount, , , ) = c.pendingFlashDecision(target, address(this));

        // The caller now withdraws.
        uint256 balBefore = token.balanceOf(address(this));
        c.withdrawGovernanceAsset(target, address(token));
        uint256 balAfter = token.balanceOf(address(this));

        // Postcondition: record at (target, this) must be cleared.
        (uint256 afterAmount, , address afterAsset, ) = c.pendingFlashDecision(target, address(this));
        bool cleared = (afterAmount == 0) && (afterAsset == address(0));

        // The reference deletes the entry; the mutant leaves it with the old amount.
        // Also, the transfer succeeded so the caller received the funds.
        assertTrue(balAfter == balBefore + beforeAmount && cleared);
    }
}

