// A DAO stub that reports successful proposals and can be configured with a
// token that succeeds at transferFrom, so assertGovernanceApproved can run.
contract SuccessfulStub {
    address public tokenAddr;
    constructor(address _token) {
        tokenAddr = _token;
    }
    function successfulProposal(address) external pure returns (bool) { return true; }
    function getFlashGoverner() external view returns (address) { return address(this); }
    function proposalConfig() external view returns (uint256, uint256, address) { return (0, 0, address(this)); }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    uint256 public totalSupply;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
    }
    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
